"""Generate bundled clients from exercises.json; --check catches contract drift."""
import argparse
import json
import subprocess
from pathlib import Path
from product_v1.catalog import CATALOG

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    workspace=Path(__file__).resolve().parents[3]
    app=workspace/'SMART-REHAB-HUB-main/mobile_app'
    web=workspace/'SMART-REHAB-HUB-main/web_dashboard/Live Workout'
    encoded=json.dumps(CATALOG,ensure_ascii=False,separators=(',',':'))
    outputs={app/'lib/product/catalog.g.dart': "// Generated by product_v1.cloud.generate_catalog. Do not edit.\nimport 'dart:convert';\nfinal Map<String, dynamic> exerciseCatalog = jsonDecode(r'''"+encoded+"''');\nfinal List<Map<String, dynamic>> exerciseLibrary = (exerciseCatalog['exercises'] as List).cast<Map<String, dynamic>>();\nfinal List<Map<String, dynamic>> retiredExercises = (exerciseCatalog['retired_exercises'] as List? ?? []).cast<Map<String, dynamic>>();\nfinal List<Map<String, dynamic>> _historyCatalog = [...exerciseLibrary, ...retiredExercises];\nfinal Map<String, String> exerciseNames = {for (final e in _historyCatalog) e['id'] as String: e['name'] as String};\nbool isExerciseAvailable(dynamic id) => exerciseLibrary.any((e) => e['id'] == id);\nMap<String, dynamic> exerciseDetails(dynamic id) => _historyCatalog.firstWhere((e) => e['id'] == id, orElse: () => <String,dynamic>{});\n", web/'src/product/catalog.g.js': '// Generated by product_v1.cloud.generate_catalog. Do not edit.\nexport const catalog = '+encoded+';\nexport const exerciseLibrary = catalog.exercises;\nconst historyCatalog = [...exerciseLibrary, ...(catalog.retired_exercises || [])];\nexport const exerciseDetails = id => historyCatalog.find(e => e.id === id) || {};\nexport const exercises = Object.fromEntries(exerciseLibrary.map(e => [e.id, e.name]));\n'}
    for path,content in outputs.items():
        if path.suffix == '.dart':
            content=subprocess.run(['dart','format','--output=show','--summary=none'], input=content, text=True, capture_output=True, check=True).stdout
        if args.check:
            if not path.exists() or path.read_text()!=content:raise SystemExit('Catalog drift: '+str(path))
        else:path.write_text(content)
    print('Catalog clients verified' if args.check else 'Catalog clients generated')
if __name__=='__main__':main()
